class DataCompressor{constructor(){this.isCompressionSupported=typeof pako!=='undefined';this.compressionLevel=6;} async compressData(data){try{if(!this.isCompressionSupported){console.warn('Compression not supported,returning original data');return JSON.stringify(data);} const jsonString=typeof data==='string' ? data : JSON.stringify(data);const compressed=pako.gzip(jsonString,{level: this.compressionLevel});const base64Compressed=this.arrayBufferToBase64(compressed);const originalSize=new Blob([jsonString]).size;const compressedSize=new Blob([base64Compressed]).size;const compressionRatio=((originalSize-compressedSize)/originalSize*100).toFixed(1);console.log(`Compression Stats: Original: ${this.formatBytes(originalSize)} Compressed: ${this.formatBytes(compressedSize)} Saved: ${compressionRatio}%`);return base64Compressed;} catch(error){console.error('Compression failed:',error);return JSON.stringify(data);}} async decompressData(compressedData){try{if(!this.isCompressionSupported){return JSON.parse(compressedData);} const compressed=this.base64ToArrayBuffer(compressedData);const decompressed=pako.ungzip(compressed,{to: 'string'});return JSON.parse(decompressed);} catch(error){console.error('Decompression failed:',error);return JSON.parse(compressedData);}} optimizeStructure(surahData){const optimized={id: surahData.surah_id,v:{}};for(const [verseKey,verseData] of Object.entries(surahData.verses)){optimized.v[verseKey]={ar: verseData.arabic_text,bn: verseData.bangla_trans,en: verseData.english_trans};if(verseData.word_by_word){optimized.v[verseKey].w={};for(const [wordKey,wordData] of Object.entries(verseData.word_by_word)){optimized.v[verseKey].w[wordKey]={ar: wordData.words_ar,bn: wordData.translate_bn};}}} return optimized;} restoreStructure(optimizedData){const restored={surah_id: optimizedData.id,verses:{}};for(const [verseKey,verseData] of Object.entries(optimizedData.v)){restored.verses[verseKey]={arabic_text: verseData.ar,bangla_trans: verseData.bn,english_trans: verseData.en};if(verseData.w){restored.verses[verseKey].word_by_word={};for(const [wordKey,wordData] of Object.entries(verseData.w)){restored.verses[verseKey].word_by_word[wordKey]={words_ar: wordData.ar,translate_bn: wordData.bn};}}} return restored;} async storeCompressedData(key,data){try{const optimized=this.optimizeStructure(data);const compressed=await this.compressData(optimized);const storageData={compressed: true,data: compressed,timestamp: Date.now()};localStorage.setItem(key,JSON.stringify(storageData));} catch(error){console.error('Failed to store compressed data:',error);localStorage.setItem(key,JSON.stringify({compressed: false,data: data,timestamp: Date.now()}));}} async retrieveCompressedData(key){try{const stored=localStorage.getItem(key);if(!stored) return null;const storageData=JSON.parse(stored);if(storageData.compressed){const decompressed=await this.decompressData(storageData.data);return this.restoreStructure(decompressed);} else{return storageData.data;}} catch(error){console.error('Failed to retrieve compressed data:',error);return null;}} arrayBufferToBase64(buffer){let binary='';const bytes=new Uint8Array(buffer);for(let i=0;i<bytes.byteLength;i++){binary+=String.fromCharCode(bytes[i]);} return btoa(binary);} base64ToArrayBuffer(base64){const binaryString=atob(base64);const bytes=new Uint8Array(binaryString.length);for(let i=0;i<binaryString.length;i++){bytes[i]=binaryString.charCodeAt(i);} return bytes;} formatBytes(bytes,decimals=2){if(bytes===0) return '0 Bytes';const k=1024;const dm=decimals<0 ? 0 : decimals;const sizes=['Bytes','KB','MB','GB'];const i=Math.floor(Math.log(bytes)/Math.log(k));return parseFloat((bytes/Math.pow(k,i)).toFixed(dm))+' '+sizes[i];} async testCompression(sampleData){console.log('Testing compression...');const compressed=await this.compressData(sampleData);const decompressed=await this.decompressData(compressed);console.log('Original:',sampleData);console.log('Decompressed:',decompressed);console.log('Data integrity:',JSON.stringify(sampleData)===JSON.stringify(decompressed));return{originalSize: JSON.stringify(sampleData).length,compressedSize: compressed.length,integrityCheck: JSON.stringify(sampleData)===JSON.stringify(decompressed)};}} if(typeof module!=='undefined'&&module.exports){module.exports=DataCompressor;} else{window.DataCompressor=DataCompressor;}